('q_dej-1-minulost-pritomnost_2','Co se stane zítra, je…',ARRAY['budoucnost','včerejšek','přítomnost','minulost']::TEXT[],0,'Zítra je budoucnost.',1,ARRAY[]::TEXT[],NULL,2,'c_dej-1-minulost-pritomnost',NULL,NOW()),
